from pathlib import Path
import json, statistics, math
from collections import Counter, defaultdict
root = Path('evals/files/private-corpus')
jsonl = [p for p in root.rglob('*.jsonl') if p.is_file()][0]
records=[]
bad=0
with jsonl.open('r', encoding='utf-8') as f:
    for line in f:
        if not line.strip():
            continue
        try:
            obj=json.loads(line)
        except Exception:
            bad += 1
            continue
        records.append(obj)
print(f'records={len(records)} malformed_jsonl={bad}')

def kind(v):
    if v is None: return 'null'
    if isinstance(v,bool): return 'bool'
    if isinstance(v,(int,float)): return 'number'
    if isinstance(v,str): return 'string'
    if isinstance(v,list): return 'array'
    if isinstance(v,dict): return 'object'
    return type(v).__name__

def walk(objs, prefix=''):
    types=Counter(); string_lengths=[]; array_lengths=[]; numeric=[]; nulls=0
    child_objects=[]
    for obj in objs:
        if prefix:
            cur=obj
            for key in prefix.split('.'):
                if not isinstance(cur,dict) or key not in cur:
                    cur=None; break
                cur=cur[key]
            v=cur
        else:
            v=obj
        types[kind(v)]+=1
        if isinstance(v,str): string_lengths.append(len(v.encode('utf-8')))
        elif isinstance(v,list): array_lengths.append(len(v))
        elif isinstance(v,(int,float)) and not isinstance(v,bool): numeric.append(float(v))
        if v is None: nulls += 1
        if isinstance(v,dict):
            child_objects.append(v)
    n=len(objs)
    extras=[]
    if string_lengths: extras.append(f'utf8_len[min/med/max]={min(string_lengths)}/{statistics.median(string_lengths):g}/{max(string_lengths)}')
    if array_lengths: extras.append(f'array_len[min/med/max]={min(array_lengths)}/{statistics.median(array_lengths):g}/{max(array_lengths)}')
    if numeric: extras.append(f'num[min/med/max]={min(numeric):g}/{statistics.median(numeric):g}/{max(numeric):g}')
    print(f'field={prefix or \"[root]\"} present={sum(types.values())}/{n} types={dict(types)}' + (' ' + ' '.join(extras) if extras else ''))
    keys=[]; seen=set()
    for child in child_objects:
        for key in child:
            if key not in seen:
                seen.add(key); keys.append(key)
    for key in keys:
        walk(child_objects, f'{prefix}.{key}' if prefix else key)

walk(records)

# Safe low-cardinality values only for schema-descriptive keys, with string values redacted unless short identifier enum.
safe_keys={'role','type','kind','format','modality','mime_type','content_type','stream','streaming'}
occ=defaultdict(Counter)
for rec in records:
    stack=[([],rec)]
    while stack:
        path,obj=stack.pop()
        if isinstance(obj,dict):
            for k,v in obj.items():
                p=path+[k]
                if k in safe_keys and isinstance(v,(str,bool,int,float)) and len(str(v))<=40:
                    occ['.'.join(p)][str(v)] += 1
                elif isinstance(v,(dict,list)):
                    stack.append((p,v))
        elif isinstance(obj,list):
            for v in obj:
                if isinstance(v,(dict,list)):
                    stack.append((path,v))
for key,vals in sorted(occ.items()):
    print(f'enum field={key} distinct={len(vals)} counts={dict(vals)}')
