from pathlib import Path
import json, re, math, statistics, unicodedata
p=next(Path('evals/files/private-corpus').rglob('*.jsonl'))
rows=[json.loads(line) for line in p.read_text(encoding='utf-8').splitlines() if line.strip()]

def summarize_strings(field):
    vals=[r[field] for r in rows]
    n=len(vals); totals={'chars':0,'whitespace_tokens':0,'lines':0,'cjk':0,'ascii':0,'nonascii':0,'punct':0,'digits':0}
    per=[]
    for v in vals:
        d={
          'chars':len(v),
          'whitespace_tokens':len(re.findall(r'\\S+',v)),
          'lines':v.count('\\n')+1,
          'cjk':sum(1 for c in v if '\\u3400'<=c<='\\u9fff' or '\\uf900'<=c<='\\ufaff'),
          'ascii':sum(1 for c in v if ord(c)<128),
          'nonascii':sum(1 for c in v if ord(c)>=128),
          'punct':sum(1 for c in v if unicodedata.category(c).startswith('P')),
          'digits':sum(1 for c in v if c.isdigit()),
        }
        per.append(d)
        for k,x in d.items():totals[k]+=x
    print(f'{field}_shape: ' + ' '.join(f'{k}=total:{totals[k]},p50:{statistics.median(x[k] for x in per):g},max:{max(x[k] for x in per)}' for k in totals))

for f in ('input','output'): summarize_strings(f)

def band(x, cuts):
    for lo,hi in zip([None]+cuts,cuts+[None]):
        if (lo is None or x>=lo) and (hi is None or x<hi):
            return f'{lo if lo is not None else \"min\"}-{hi-1 if hi is not None else \"max\"}'
    return 'other'
def report(field,cuts):
    groups={}
    for r in rows: groups.setdefault(band(r[field],cuts),[]).append(r)
    print(f'bins_{field}_cuts={cuts}')
    for name,g in groups.items():
        lat=sorted(r['latencyMs'] for r in g)
        med=statistics.median(lat)
        print(f'band={name} records={len(g)} field_total={sum(r[field] for r in g):g} latency_p50={med:g} latency_max={max(lat):g}')
report('inputBytes',[256,1024,4096])
report('items',[10,100,256])
report('latencyMs',[50,150,300])
PY"

